"use client";

import { cn } from "@/lib/utils";
import gsap from "gsap";
import * as React from "react";

export interface EditorialImageStackImage {
  /** Image source used inside the stack. */
  src: string;
  /** Accessible description. Foreground images should always provide one. */
  alt?: string;
}

export interface EditorialImageStackProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
  /** Photographs that form the shuffled background stack. Up to eight render. */
  backgroundImages: readonly EditorialImageStackImage[];
  /** Photographs that crossfade inside the stationary foreground card. */
  foregroundImages: readonly EditorialImageStackImage[];
  /** Animate the background stack. @default true */
  autoRotate?: boolean;
  /** Milliseconds between foreground image changes. @default 1100 */
  switchIntervalMs?: number;
  /** Foreground blur-crossfade duration in milliseconds. @default 300 */
  transitionMs?: number;
  /** Multiplier applied to the 330px center card. @default 1.4 */
  centerScale?: number;
  /** Number of background cards to render. @default 7 */
  bgCardCount?: number;
  /** Background offset radius as a fraction of the center card size. @default 0.31 */
  bgSpread?: number;
  /** Background card opacity. @default 0.7 */
  bgOpacity?: number;
  /** Maximum background card rotation in degrees. @default 25 */
  bgRotationRange?: number;
  /** Accessible name for the gallery region. */
  ariaLabel?: string;
}

export const SWITCH_INTERVAL_MS = 1100;
export const TRANSITION_MS = 300;
export const CENTER_SCALE = 1.4;
export const BG_CARD_COUNT = 7;
export const BG_SPREAD = 0.31;
export const BG_OPACITY = 0.7;
export const BG_ROTATION_RANGE = 25;

const STAGE_WIDTH = 760;
const STAGE_HEIGHT = 700;
const CENTER_BASE_SIZE = 330;
const BACKGROUND_LIMIT = 8;
const BG_CARD_WIDTH_RATIO = 0.47;
const BG_CARD_HEIGHT_RATIO = 0.62;
const BG_SHUFFLE_MS = 360;
const DRIFT_RANGE_DEG = 4.5;
const DRIFT_PERIOD_MS = 9000;
const BLUR_PX = 6;
const FOREGROUND_Z = 30;
const TINT_COLORS = [
  "#ff5a36",
  "#3ec7ff",
  "#ffd166",
  "#a78bfa",
  "#ff7bac",
] as const;

interface BackgroundTarget {
  x: number;
  y: number;
  rotation: number;
}

const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? React.useLayoutEffect : React.useEffect;

function seeded(index: number, step: number, offset: number) {
  const value =
    Math.sin((index + 1) * 12.9898 + step * 78.233 + offset * 37.719) *
    43758.5453;
  return value - Math.floor(value);
}

function getBackgroundTarget(
  index: number,
  count: number,
  step: number,
  radius: number,
  rotationRange: number,
): BackgroundTarget {
  const gap = 360 / count;
  const angle = gap * index + step * 9 + (seeded(index, 0, 1) - 0.5) * gap * 0.42;
  const localRadius = radius * (0.88 + seeded(index, 0, 2) * 0.18);
  const radians = (angle * Math.PI) / 180;
  const rotation = (seeded(index, step, 3) * 2 - 1) * rotationRange;

  return {
    x: Math.cos(radians) * localRadius,
    y: Math.sin(radians) * localRadius,
    rotation,
  };
}

function usePrefersReducedMotion() {
  const [reducedMotion, setReducedMotion] = React.useState(false);
  const reducedMotionRef = React.useRef(false);

  React.useEffect(() => {
    if (
      typeof window === "undefined" ||
      typeof window.matchMedia !== "function"
    ) {
      return;
    }

    const query = window.matchMedia("(prefers-reduced-motion: reduce)");
    const sync = () => {
      reducedMotionRef.current = query.matches;
      setReducedMotion(query.matches);
    };

    sync();

    if (typeof query.addEventListener === "function") {
      query.addEventListener("change", sync);
      return () => query.removeEventListener("change", sync);
    }

    query.addListener(sync);
    return () => query.removeListener(sync);
  }, []);

  return { reducedMotion, reducedMotionRef };
}

/**
 * A photographic deck with a large fixed center card and a subdued stack of
 * background photographs that shuffles in sync with every image change.
 */
export function EditorialImageStack({
  backgroundImages,
  foregroundImages,
  autoRotate = true,
  switchIntervalMs = SWITCH_INTERVAL_MS,
  transitionMs = TRANSITION_MS,
  centerScale = CENTER_SCALE,
  bgCardCount = BG_CARD_COUNT,
  bgSpread = BG_SPREAD,
  bgOpacity = BG_OPACITY,
  bgRotationRange = BG_ROTATION_RANGE,
  ariaLabel,
  className,
  style,
  ...props
}: EditorialImageStackProps) {
  const centerSize = Math.round(CENTER_BASE_SIZE * Math.max(0.8, centerScale));
  const safeBgCount = Math.max(
    0,
    Math.min(BACKGROUND_LIMIT, Math.floor(bgCardCount)),
  );
  const bgCardWidth = Math.round(centerSize * BG_CARD_WIDTH_RATIO);
  const bgCardHeight = Math.round(centerSize * BG_CARD_HEIGHT_RATIO);
  const bgRadius = centerSize * Math.min(0.6, Math.max(0.1, bgSpread));
  const safeRotation = Math.min(60, Math.max(0, bgRotationRange));
  const safeOpacity = Math.min(1, Math.max(0, bgOpacity));
  const safeInterval = Math.max(250, switchIntervalMs);
  const safeTransition = Math.max(0, transitionMs);

  const backgroundCards = React.useMemo(
    () => backgroundImages.slice(0, safeBgCount),
    [backgroundImages, safeBgCount],
  );
  const foregroundSignature = React.useMemo(
    () => foregroundImages.map((image) => image.src).join("\u0000"),
    [foregroundImages],
  );
  const foregroundCount = foregroundImages.length;

  const rootRef = React.useRef<HTMLDivElement>(null);
  const rotatingRef = React.useRef<HTMLDivElement>(null);
  const baseRef = React.useRef<HTMLImageElement>(null);
  const overlayRef = React.useRef<HTMLImageElement>(null);
  const tintRef = React.useRef<HTMLDivElement>(null);
  const backgroundCardRefs = React.useRef<Array<HTMLDivElement | null>>([]);
  const baseIndexRef = React.useRef(0);
  const overlayIndexRef = React.useRef(foregroundCount > 1 ? 1 : 0);
  const isTransitioningRef = React.useRef(false);
  const isMountedRef = React.useRef(false);
  const transitionIdRef = React.useRef(0);
  const stepRef = React.useRef(0);

  const [baseIndex, setBaseIndex] = React.useState(0);
  const [overlayIndex, setOverlayIndex] = React.useState(
    foregroundCount > 1 ? 1 : 0,
  );
  const [imagesReady, setImagesReady] = React.useState(false);
  const [inView, setInView] = React.useState(true);
  const [pageVisible, setPageVisible] = React.useState(true);
  const { reducedMotion, reducedMotionRef } = usePrefersReducedMotion();

  React.useEffect(() => {
    isMountedRef.current = true;
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  React.useEffect(() => {
    const root = rootRef.current;
    if (!root) return;

    const measure = () => {
      const rect = root.getBoundingClientRect();
      if (!rect.width || !rect.height) return;
      const scale = Math.min(
        rect.width / STAGE_WIDTH,
        rect.height / STAGE_HEIGHT,
        1,
      );
      root.style.setProperty(
        "--editorial-image-stack-scale",
        String(Math.max(0.2, scale)),
      );
    };

    measure();

    if (typeof ResizeObserver === "undefined") {
      window.addEventListener("resize", measure);
      return () => window.removeEventListener("resize", measure);
    }

    const observer = new ResizeObserver(measure);
    observer.observe(root);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const node = rootRef.current;
    if (!node) return;

    if (typeof IntersectionObserver === "undefined") {
      setInView(true);
      return;
    }

    const observer = new IntersectionObserver(
      ([entry]) => setInView(Boolean(entry?.isIntersecting)),
      { rootMargin: "160px" },
    );

    observer.observe(node);
    return () => observer.disconnect();
  }, []);

  React.useEffect(() => {
    const sync = () => setPageVisible(!document.hidden);
    sync();
    document.addEventListener("visibilitychange", sync);
    return () => document.removeEventListener("visibilitychange", sync);
  }, []);

  React.useEffect(() => {
    setImagesReady(false);

    if (foregroundCount === 0) {
      setImagesReady(true);
      return;
    }

    let cancelled = false;
    const sources = Array.from(
      new Set(foregroundImages.map((image) => image.src)),
    );
    const preloaders: HTMLImageElement[] = [];
    let remaining = sources.length;

    const settle = () => {
      remaining -= 1;
      if (remaining <= 0 && !cancelled) {
        setImagesReady(true);
      }
    };

    for (const src of sources) {
      const preloader = new window.Image();
      preloader.decoding = "async";
      preloader.onload = () => {
        if (typeof preloader.decode === "function") {
          void preloader.decode().then(settle, settle);
          return;
        }
        settle();
      };
      preloader.onerror = settle;
      preloader.src = src;
      preloaders.push(preloader);
    }

    return () => {
      cancelled = true;
      for (const preloader of preloaders) {
        preloader.onload = null;
        preloader.onerror = null;
      }
    };
  }, [foregroundCount, foregroundImages, foregroundSignature]);

  useIsomorphicLayoutEffect(() => {
    transitionIdRef.current += 1;
    isTransitioningRef.current = false;
    gsap.killTweensOf([baseRef.current, overlayRef.current, tintRef.current]);

    baseIndexRef.current = 0;
    const nextOverlay = foregroundCount > 1 ? 1 : 0;
    overlayIndexRef.current = nextOverlay;
    setBaseIndex(0);
    setOverlayIndex(nextOverlay);

    if (baseRef.current) {
      gsap.set(baseRef.current, {
        opacity: 1,
        filter: "none",
        xPercent: 0,
        scale: 1,
      });
    }
    if (overlayRef.current) {
      gsap.set(overlayRef.current, {
        opacity: 0,
        filter: "none",
        xPercent: 0,
        scale: 1,
      });
    }
    if (tintRef.current) {
      gsap.set(tintRef.current, { opacity: 0 });
    }
  }, [foregroundCount, foregroundSignature]);

  useIsomorphicLayoutEffect(() => {
    stepRef.current = 0;
    const cards = backgroundCardRefs.current;

    cards.forEach((card, index) => {
      if (!card) return;
      const target = getBackgroundTarget(
        index,
        Math.max(1, backgroundCards.length),
        0,
        bgRadius,
        safeRotation,
      );
      gsap.killTweensOf(card);
      gsap.set(card, {
        xPercent: -50,
        yPercent: -50,
        x: target.x,
        y: target.y,
        rotation: target.rotation,
      });
    });

    if (rotatingRef.current) {
      rotatingRef.current.style.transform = "rotate(0deg)";
    }

    return () => {
      cards.forEach((card) => {
        if (card) gsap.killTweensOf(card);
      });
    };
  }, [backgroundCards.length, bgRadius, safeRotation]);

  const advanceForeground = React.useCallback(() => {
    const count = foregroundImages.length;
    const base = baseRef.current;
    const overlay = overlayRef.current;
    const tint = tintRef.current;

    if (count < 2 || !base || !overlay || isTransitioningRef.current) {
      return false;
    }

    const nextBase = overlayIndexRef.current;
    const nextOverlay = (nextBase + 1) % count;
    const duration = safeTransition / 1000;
    const instant = reducedMotionRef.current || duration === 0;

    transitionIdRef.current += 1;
    const transitionId = transitionIdRef.current;

    if (instant) {
      baseIndexRef.current = nextBase;
      overlayIndexRef.current = nextOverlay;
      setBaseIndex(nextBase);
      setOverlayIndex(nextOverlay);
      gsap.set(base, {
        opacity: 1,
        filter: "none",
        xPercent: 0,
        scale: 1,
      });
      gsap.set(overlay, {
        opacity: 0,
        filter: "none",
        xPercent: 0,
        scale: 1,
      });
      gsap.set(tint, { opacity: 0 });
      return true;
    }

    gsap.killTweensOf([base, overlay, tint]);

    if (tint) {
      tint.style.backgroundColor =
        TINT_COLORS[nextBase % TINT_COLORS.length] ?? TINT_COLORS[0];
    }

    isTransitioningRef.current = true;

    const timeline = gsap.timeline({
      onComplete: () => {
        if (!isMountedRef.current || transitionId !== transitionIdRef.current) {
          return;
        }

        baseIndexRef.current = nextBase;
        setBaseIndex(nextBase);

        requestAnimationFrame(() => {
          if (
            !isMountedRef.current ||
            transitionId !== transitionIdRef.current
          ) {
            return;
          }

          requestAnimationFrame(() => {
            if (
              !isMountedRef.current ||
              transitionId !== transitionIdRef.current
            ) {
              return;
            }

            gsap.set(overlay, {
              opacity: 0,
              filter: "none",
              xPercent: 0,
              scale: 1,
            });
            gsap.set(base, {
              opacity: 1,
              filter: "none",
              xPercent: 0,
              scale: 1,
            });
            overlayIndexRef.current = nextOverlay;
            setOverlayIndex(nextOverlay);
            isTransitioningRef.current = false;
          });
        });
      },
    });

    timeline
      .set(
        overlay,
        {
          opacity: 0,
          filter: `blur(0px) saturate(1.2) hue-rotate(10deg)`,
          xPercent: 1.5,
          scale: 1.02,
        },
        0,
      )
      .to(
        overlay,
        {
          opacity: 0.86,
          filter: `blur(${BLUR_PX}px) saturate(1.28) hue-rotate(10deg)`,
          duration: duration * 0.45,
          ease: "power2.in",
        },
        0,
      )
      .to(
        overlay,
        {
          opacity: 1,
          filter: "blur(0px) saturate(1) hue-rotate(0deg)",
          xPercent: 0,
          scale: 1,
          duration: duration * 0.55,
          ease: "power2.out",
        },
        duration * 0.45,
      )
      .to(
        base,
        {
          opacity: 0.2,
          filter: `blur(${BLUR_PX}px) saturate(0.9)`,
          xPercent: -1,
          scale: 1.01,
          duration,
          ease: "power2.in",
        },
        0,
      );

    if (tint) {
      timeline
        .to(
          tint,
          {
            opacity: 0.16,
            duration: duration * 0.45,
            ease: "power2.out",
          },
          0,
        )
        .to(
          tint,
          {
            opacity: 0,
            duration: duration * 0.55,
            ease: "power2.in",
          },
          duration * 0.45,
        );
    }

    return true;
  }, [foregroundImages.length, reducedMotionRef, safeTransition]);

  const shuffleBackground = React.useCallback(
    (step: number) => {
      if (!autoRotate || reducedMotionRef.current) return;

      const cards = backgroundCardRefs.current;
      const count = Math.max(1, backgroundCards.length);

      cards.forEach((card, index) => {
        if (!card) return;
        const target = getBackgroundTarget(
          index,
          count,
          step,
          bgRadius,
          safeRotation,
        );
        gsap.to(card, {
          x: target.x,
          y: target.y,
          rotation: target.rotation,
          duration: BG_SHUFFLE_MS / 1000,
          ease: "power3.out",
          overwrite: "auto",
        });
      });
    },
    [
      autoRotate,
      backgroundCards.length,
      bgRadius,
      reducedMotionRef,
      safeRotation,
    ],
  );

  React.useEffect(() => {
    if (!inView || !pageVisible) return;

    const canMove = autoRotate && backgroundCards.length > 0;
    const canSwitch = imagesReady && foregroundCount > 1;

    if (!canMove && !canSwitch) return;

    const rotator = rotatingRef.current;
    const interval = reducedMotion
      ? Math.max(safeInterval, 2600)
      : safeInterval;
    const start = performance.now();
    let lastSwitch = start;
    let frame = 0;

    const tick = (now: number) => {
      if (rotator) {
        if (canMove && !reducedMotion) {
          const drift =
            Math.sin(((now - start) / DRIFT_PERIOD_MS) * Math.PI * 2) *
            DRIFT_RANGE_DEG;
          rotator.style.transform = `rotate(${drift}deg)`;
        } else {
          rotator.style.transform = "rotate(0deg)";
        }
      }

      if (canSwitch && now - lastSwitch >= interval) {
        lastSwitch = now;
        if (advanceForeground()) {
          stepRef.current += 1;
          if (canMove && !reducedMotion) {
            shuffleBackground(stepRef.current);
          }
        }
      }

      frame = requestAnimationFrame(tick);
    };

    frame = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(frame);
      if (rotator) rotator.style.transform = "rotate(0deg)";
    };
  }, [
    advanceForeground,
    autoRotate,
    backgroundCards.length,
    foregroundCount,
    imagesReady,
    inView,
    pageVisible,
    reducedMotion,
    safeInterval,
    shuffleBackground,
  ]);

  React.useEffect(() => {
    const base = baseRef.current;
    const overlay = overlayRef.current;
    const tint = tintRef.current;

    return () => {
      gsap.killTweensOf([base, overlay, tint]);
    };
  }, []);

  const baseImage = foregroundImages[baseIndex] ?? foregroundImages[0];
  const overlayImage = foregroundImages[overlayIndex] ?? foregroundImages[0];

  return (
    <div
      {...props}
      ref={rootRef}
      role="region"
      aria-roledescription="image stack"
      aria-label={props["aria-label"] ?? ariaLabel ?? "Editorial image stack"}
      data-slot="editorial-image-stack"
      className={cn(
        "editorial-image-stack relative isolate flex h-full min-h-[420px] w-full items-center justify-center overflow-hidden bg-[#e5e5e5] text-neutral-950 dark:bg-[#151515] dark:text-neutral-100",
        className,
      )}
      style={style}
    >
      <div
        data-slot="editorial-image-stack-stage"
        className="relative shrink-0"
        style={{
          width: STAGE_WIDTH,
          height: STAGE_HEIGHT,
          transform: "scale(var(--editorial-image-stack-scale, 1))",
          transformOrigin: "50% 50%",
          willChange: "transform",
        }}
      >
        {backgroundCards.length > 0 ? (
          <div aria-hidden="true" className="absolute inset-0">
            <div
              ref={rotatingRef}
              data-slot="editorial-image-stack-rotator"
              className="absolute inset-0"
              style={{ transformOrigin: "50% 50%", willChange: "transform" }}
            >
              {backgroundCards.map((image, index) => (
                <div
                  key={`${image.src}-${index}`}
                  ref={(node) => {
                    backgroundCardRefs.current[index] = node;
                  }}
                  data-slot="editorial-image-stack-background-card"
                  className="absolute left-1/2 top-1/2 overflow-hidden rounded-none bg-black shadow-[0_18px_50px_-26px_rgba(0,0,0,0.9)] ring-1 ring-white/5"
                  style={{
                    width: bgCardWidth,
                    height: bgCardHeight,
                    opacity: safeOpacity,
                    zIndex: index + 1,
                    willChange: "transform, opacity",
                  }}
                >
                  <img
                    src={image.src}
                    alt=""
                    draggable={false}
                    loading="eager"
                    decoding="async"
                    className="block h-full w-full select-none object-cover"
                    style={{
                      filter: "brightness(0.62) saturate(0.55) contrast(1.08)",
                    }}
                  />
                  <div className="absolute inset-0 bg-black/20" />
                </div>
              ))}
            </div>
          </div>
        ) : null}

        {foregroundImages.length > 0 ? (
          <div
            data-slot="editorial-image-stack-foreground"
            className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 overflow-hidden rounded-none bg-[#d8d3c8] shadow-[0_36px_80px_-36px_rgba(0,0,0,0.7)] ring-1 ring-black/5 dark:bg-[#1a1a1a] dark:ring-white/10"
            style={{
              width: centerSize,
              height: centerSize,
              zIndex: FOREGROUND_Z,
            }}
          >
            <img
              ref={baseRef}
              data-slot="editorial-image-stack-foreground-base"
              src={baseImage?.src}
              alt={baseImage?.alt ?? ""}
              draggable={false}
              loading="eager"
              decoding="async"
              className="absolute inset-0 block h-full w-full select-none object-cover"
              style={{ willChange: "transform, opacity, filter" }}
            />
            <img
              ref={overlayRef}
              data-slot="editorial-image-stack-foreground-overlay"
              src={overlayImage?.src}
              alt=""
              aria-hidden="true"
              draggable={false}
              loading="eager"
              decoding="async"
              className="absolute inset-0 block h-full w-full select-none object-cover"
              style={{
                opacity: 0,
                willChange: "transform, opacity, filter",
              }}
            />
            <div
              ref={tintRef}
              aria-hidden="true"
              data-slot="editorial-image-stack-foreground-tint"
              className="pointer-events-none absolute inset-0 opacity-0 mix-blend-soft-light"
              style={{ willChange: "opacity" }}
            />
          </div>
        ) : null}
      </div>
    </div>
  );
}

export default EditorialImageStack;
